"""Reproducible visual-type research of the 405 unresolved photographs.
These observations never establish a warehouse SKU or certify a standard.
"""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
source=json.loads((root/'docs/product-image-review.json').read_text())
unresolved={int(x['file'][2:-5]):x for x in source['items'] if not x['familyCode']}
research={}
def group(numbers,kind,features,measurements):
 for token in numbers.split(','):
  span=token.strip().split('-')
  for n in range(int(span[0]),int(span[-1])+1):
   if n not in unresolved:continue
   assert n not in research,(n,kind)
   research[n]={'file':f'e({n}).png','sourceSha256':unresolved[n]['sha256'],'visualType':kind,'visibleFeatures':features,'requiredChecks':measurements.split('|'),'identityStatus':'visual-type-only','standardStatus':'not-established','exactSku':None,'reason':'نام‌گذاری پیشنهادی از روی شکل؛ ابعاد، جنس، کد سفارش و انطباق استاندارد از عکس بدون نشانه تأیید نمی‌شوند.'}
