missing=sorted(set(unresolved)-set(research))
if missing:raise SystemExit(f'Unreviewed files: {missing}')
out={'reviewDate':'2026-10-19','scope':'405 unresolved images; visual morphology only, not exact SKU identification or standard certification','items':[research[n] for n in sorted(research)]}
(root/'src/data/imageResearch.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print({'reviewed':len(research),'exactSkuIdentifications':0,'visualTypes':len(set(x['visualType'] for x in research.values()))})
